        };
        public class EyeDetector : Detector
        {
            public EyeDetector(bool green)
            {
                this.green = green;
            }
            protected override Bounds GetDetectionBounds(Entity self)
            {
                var position = GetEyePosition(self, green);
                var sizeX = 8000;
                var sizeY = 40;
                var sizeZ = 360;
                var centerX = position.x + sizeX * 0.5f * self.GetFacingX();
                var centerY = position.y;
                var centerZ = position.z;
                return new Bounds(new Vector3(centerX, centerY, centerZ), new Vector3(sizeX, sizeY, sizeZ));
            }
            public bool green;
        }
    }
